setLessCommboToDb = function(ymst, obj) {
			try {
				var data = {
					SP_YMST :ymst
				};
				fsp.clear();
				fsp.addSearch("admin:LESS_SEARCH");
				fsp.callService(
					""
					, ""
					, data
					, function(errorCode, rData){
						try {
							var ds =  rData.ds_less;

							if( ds.length > 0 ) {
								for(var i = 0; i < ds.length; i++) {
									$('#' + obj).append($('<option>').val(ds[i].ORGN_CD).text(' ' + setLabel(ds[i].ORGN_NM, ds[i].ORGN_ENM)));	
								}
							}
						} catch( ee ) {
							
						}
					}// end success 
				);
			} catch( eee ) {
				fsp.common.jsError("#fn_init" , eee);
			}
	};
	
